function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the original
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys + tasks in dependencies)
  const allTasks = new Set();
  for (const key in graphCopy) {
    allTasks.add(key);
    for (const dep of graphCopy[key]) {
      allTasks.add(dep);
    }
  }

  // Build dependency count for each task
  const depCount = {};
  for (const task of allTasks) {
    depCount[task] = 0;
  }

  // Count dependencies for each task
  for (const key in graphCopy) {
    for (const dep of graphCopy[key]) {
      depCount[dep]++;
    }
  }

  // Find tasks with no dependencies
  const readyTasks = [];
  for (const task of allTasks) {
    if (depCount[task] === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks alphabetically
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Pick the lexicographically smallest task
    const current = readyTasks.shift();
    result.push(current);

    // Remove this task from dependencies of others
    for (const key in graphCopy) {
      const deps = graphCopy[key];
      const index = deps.indexOf(current);
      if (index !== -1) {
        deps.splice(index, 1);
        depCount[key]--;

        // If a task now has no dependencies, add it to ready tasks
        if (depCount[key] === 0) {
          readyTasks.push(key);
          readyTasks.sort();
        }
      }
    }
  }

  // Check for cycles
  if (result.length !== allTasks.size) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
