from datetime import datetime, timedelta

def business_days(start, end, holidays=()):
    # Validate and parse dates
    try:
        start_date = datetime.strptime(start, "%Y-%m-%d").date()
        end_date = datetime.strptime(end, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Invalid date format")

    if end_date < start_date:
        raise ValueError("end must not be earlier than start")

    # Convert holidays to set of dates for efficient lookup
    holiday_set = set()
    for holiday in holidays:
        try:
            holiday_date = datetime.strptime(holiday, "%Y-%m-%d").date()
            # Only consider holidays that fall on weekdays and are within range
            if holiday_date.weekday() < 5 and start_date <= holiday_date < end_date:
                holiday_set.add(holiday_date)
        except ValueError:
            raise ValueError("Invalid date format in holidays")

    # Count business days
    count = 0
    current_date = start_date

    while current_date < end_date:
        # Check if current date is a weekday (Monday=0, Sunday=6)
        if current_date.weekday() < 5 and current_date not in holiday_set:
            count += 1
        current_date += timedelta(days=1)

    return count
