def flatten(obj, sep="."):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    result = {}

    def _flatten(current, parent_key=""):
        for key, value in current.items():
            # Convert key to string
            str_key = str(key)

            # Build new key
            if parent_key:
                new_key = f"{parent_key}{sep}{str_key}"
            else:
                new_key = str_key

            if isinstance(value, dict):
                # Recursively flatten nested dict
                _flatten(value, new_key)
            elif isinstance(value, list):
                # Handle list by iterating through elements
                if not value:  # Empty list
                    result[new_key] = value
                else:
                    for i, item in enumerate(value):
                        list_key = f"{new_key}{sep}{i}"
                        if isinstance(item, (dict, list)):
                            # Recursively flatten nested dict or list
                            _flatten({0: item}, list_key)
                        else:
                            # Leaf value
                            result[list_key] = item
            else:
                # Leaf value
                result[new_key] = value

    _flatten(obj)
    return result
