function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  if (!spec.trim()) {
    return [];
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmedPart = part.trim();

    if (trimmedPart === '') {
      throw new SyntaxError('Empty part in specification');
    }

    if (trimmedPart.includes('.')) {
      throw new SyntaxError('Decimal numbers not allowed');
    }

    if (trimmedPart.includes('+')) {
      throw new SyntaxError('Plus sign not allowed');
    }

    if (trimmedPart.includes('-')) {
      const dashCount = (trimmedPart.match(/-/g) || []).length;
      if (dashCount !== 1) {
        throw new SyntaxError('Invalid range format');
      }

      const [lowStr, highStr] = trimmedPart.split('-');

      if (lowStr === '' || highStr === '') {
        throw new SyntaxError('Missing range bounds');
      }

      if (/[^\d]/.test(lowStr) || /[^\d]/.test(highStr)) {
        throw new SyntaxError('Non-numeric characters in range');
      }

      const low = parseInt(lowStr, 10);
      const high = parseInt(highStr, 10);

      if (isNaN(low) || isNaN(high)) {
        throw new SyntaxError('Invalid numeric values in range');
      }

      if (low > high) {
        throw new RangeError('Range start greater than end');
      }

      for (let i = low; i <= high; i++) {
        result.add(i);
      }
    } else {
      if (/[^\d]/.test(trimmedPart)) {
        throw new SyntaxError('Non-numeric characters in part');
      }

      const num = parseInt(trimmedPart, 10);

      if (isNaN(num)) {
        throw new SyntaxError('Invalid numeric value');
      }

      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

