function ageOn(birth, on) {
  // Validate date format
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(birth) || !dateRegex.test(on)) {
    throw new RangeError('Invalid date format');
  }

  // Parse dates
  const birthDate = new Date(birth);
  const onDate = new Date(on);

  // Validate valid dates
  if (birthDate.toString() === 'Invalid Date' || onDate.toString() === 'Invalid Date') {
    throw new RangeError('Invalid date');
  }

  // Check if on date is before birth date
  if (onDate < birthDate) {
    throw new RangeError('on date cannot be earlier than birth date');
  }

  // Calculate age
  let age = onDate.getFullYear() - birthDate.getFullYear();

  // Check if birthday has occurred this year
  const birthMonth = birthDate.getMonth();
  const birthDay = birthDate.getDate();
  const onMonth = onDate.getMonth();
  const onDay = onDate.getDate();

  // If we're before the birthday in the current year, subtract one year
  if (onMonth < birthMonth || (onMonth === birthMonth && onDay < birthDay)) {
    age--;
  }

  // Handle leap year birthday
  if (birthMonth === 1 && birthDay === 29) { // February 29
    // Check if current year is a leap year
    const currentYear = onDate.getFullYear();
    const isLeapYear = (currentYear % 4 === 0 && currentYear % 100 !== 0) || (currentYear % 400 === 0);

    // If not a leap year and birthday hasn't occurred yet, adjust
    if (!isLeapYear && (onMonth < 2 || (onMonth === 2 && onDay < 29))) {
      age--;
    }
  }

  return age;
}

module.exports = { ageOn };

