function longestCommonPrefix(strs) {
  // Type checking
  if (!Array.isArray(strs)) {
    throw new TypeError('Argument must be an array');
  }

  for (let i = 0; i < strs.length; i++) {
    if (typeof strs[i] !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  // Handle edge cases
  if (strs.length === 0) {
    return '';
  }

  if (strs.length === 1) {
    return strs[0];
  }

  // Find the shortest string length
  let minLength = Infinity;
  for (let i = 0; i < strs.length; i++) {
    if (strs[i].length < minLength) {
      minLength = strs[i].length;
    }
  }

  // Compare character by character
  let prefix = '';

  for (let i = 0; i < minLength; i++) {
    const char = strs[0].codePointAt(i);

    // Check if all strings have the same character at position i
    let allMatch = true;
    for (let j = 1; j < strs.length; j++) {
      if (strs[j].codePointAt(i) !== char) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) {
      // Append the character to prefix
      prefix += String.fromCodePoint(char);
    } else {
      break;
    }
  }

  return prefix;
}

